    _type: EventType,
    _listener: (
      this: WebSocket,
      event: WebSocketClientEventMap[EventType],
    ) => void,
    _options?: AddEventListenerOptions | boolean,
  ): void {
    throw new Error(
      'WebSocketRemoteClientConnection.addEventListener is not supported',
    )
  }

