    _event: EventType,
    _listener: (
      this: WebSocket,
      event: WebSocketClientEventMap[EventType],
    ) => void,
    _options?: EventListenerOptions | boolean,
  ): void {
    throw new Error(
      'WebSocketRemoteClientConnection.removeEventListener is not supported',
    )
  }
}
